/* ==========================================================
   Developer Portfolio — script
   各セクションは独立した関数にして、無効化しやすくしています。
   ========================================================== */
(() => {
  "use strict";

  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const prefersReduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const isFine = matchMedia("(hover: hover)").matches;
  const mouse = { x: innerWidth / 2, y: innerHeight / 2, tx: innerWidth / 2, ty: innerHeight / 2 };

  /* ---------- 1. ブートシーケンス ---------- */
  function boot() {
    const lines = [
      "> initializing creative engine...",
      "> loading shaders ............ OK",
      "> compiling particles ........ OK",
      "> mounting reality ........... OK",
      "> welcome, visitor.",
    ];
    const out = $("#bootText");
    const loader = $("#loader");
    let i = 0;
    const tick = () => {
      if (i < lines.length) {
        out.textContent += lines[i++] + "\n";
        setTimeout(tick, 260);
      } else {
        setTimeout(() => {
          loader.classList.add("done");
          document.body.classList.remove("locked");
          revealOnScroll();
          startTyping();
        }, 400);
      }
    };
    document.body.classList.add("locked");
    tick();
    // 念のため：JS停止時にもローダーが残らないように
    setTimeout(() => loader.classList.add("done"), 5000);
  }

  /* ---------- 2. カスタムカーソル + マグネット効果 ---------- */
  function cursor() {
    if (!isFine) return;
    const dot = $("#cursorDot"), ring = $("#cursorRing");
    let rx = innerWidth / 2, ry = innerHeight / 2;
    addEventListener("mousemove", (e) => {
      mouse.tx = e.clientX; mouse.ty = e.clientY;
      dot.style.left = e.clientX + "px";
      dot.style.top = e.clientY + "px";
    });
    (function loop() {
      rx += (mouse.tx - rx) * 0.15;
      ry += (mouse.ty - ry) * 0.15;
      ring.style.left = rx + "px";
      ring.style.top = ry + "px";
      requestAnimationFrame(loop);
    })();
    $$("a, button, .tilt, .lab-magnet").forEach((el) => {
      el.addEventListener("mouseenter", () => ring.classList.add("hover"));
      el.addEventListener("mouseleave", () => ring.classList.remove("hover"));
    });
    // マグネット：ボタンがカーソルに引き寄せられる
    $$(".magnetic").forEach((el) => {
      el.addEventListener("mousemove", (e) => {
        const r = el.getBoundingClientRect();
        const x = (e.clientX - r.left - r.width / 2) * 0.3;
        const y = (e.clientY - r.top - r.height / 2) * 0.3;
        el.style.transform = `translate(${x}px, ${y}px)`;
      });
      el.addEventListener("mouseleave", () => (el.style.transform = ""));
    });
  }

  /* ---------- 3. 背景パーティクル（マウスに反応） ---------- */
  function particles() {
    if (prefersReduced) return;
    const canvas = $("#bg"), ctx = canvas.getContext("2d");
    let w, h, pts;
    const resize = () => {
      w = canvas.width = innerWidth * devicePixelRatio;
      h = canvas.height = innerHeight * devicePixelRatio;
      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
      const n = Math.min(140, Math.floor((innerWidth * innerHeight) / 12000));
      pts = Array.from({ length: n }, () => ({
        x: Math.random() * innerWidth,
        y: Math.random() * innerHeight,
        vx: 0, vy: 0,
        r: Math.random() * 1.8 + 0.4,
        hue: Math.random() < 0.5 ? 160 : 320,
      }));
    };
    resize();
    addEventListener("resize", resize);
    addEventListener("mousemove", (e) => { mouse.x = e.clientX; mouse.y = e.clientY; });

    (function frame() {
      ctx.clearRect(0, 0, innerWidth, innerHeight);
      const isDark = document.documentElement.dataset.theme !== "light";
      for (const p of pts) {
        const dx = p.x - mouse.x, dy = p.y - mouse.y;
        const d2 = dx * dx + dy * dy;
        if (d2 < 220 * 220) {
          const f = (1 - Math.sqrt(d2) / 220) * 0.6;
          p.vx += (dx / Math.sqrt(d2 + 1)) * f;
          p.vy += (dy / Math.sqrt(d2 + 1)) * f;
        }
        p.vx *= 0.94; p.vy *= 0.94;
        p.x += p.vx + Math.sin(p.y * 0.01 + performance.now() * 0.0005) * 0.15;
        p.y += p.vy + 0.12;
        if (p.y > innerHeight) { p.y = -4; p.x = Math.random() * innerWidth; }
        if (p.x < 0) p.x = innerWidth; if (p.x > innerWidth) p.x = 0;

        ctx.beginPath();
        ctx.fillStyle = `hsla(${p.hue}, 90%, ${isDark ? 70 : 35}%, 0.8)`;
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fill();
      }
      // 近いパーティクル同士を線で結ぶ
      ctx.lineWidth = 0.5;
      for (let i = 0; i < pts.length; i++) {
        for (let j = i + 1; j < pts.length; j++) {
          const a = pts[i], b = pts[j];
          const dx = a.x - b.x, dy = a.y - b.y;
          const d = Math.hypot(dx, dy);
          if (d < 110) {
            ctx.strokeStyle = `rgba(124,247,212,${(1 - d / 110) * 0.18})`;
            ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
          }
        }
      }
      requestAnimationFrame(frame);
    })();
  }

  /* ---------- 4. ヒーローの3D有機オーブ（Canvas2D） ---------- */
  function orb() {
    if (prefersReduced) return;
    const canvas = $("#orb"), ctx = canvas.getContext("2d");
    const resize = () => {
      const r = canvas.getBoundingClientRect();
      canvas.width = r.width * devicePixelRatio;
      canvas.height = r.height * devicePixelRatio;
      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
    };
    resize();
    addEventListener("resize", resize);

    // 球面上に点を配置し、ノイズで歪ませる
    const N = 900;
    const pts = Array.from({ length: N }, (_, i) => {
      const phi = Math.acos(1 - (2 * (i + 0.5)) / N);
      const theta = Math.PI * (1 + Math.sqrt(5)) * i;
      return { x: Math.sin(phi) * Math.cos(theta), y: Math.sin(phi) * Math.sin(theta), z: Math.cos(phi) };
    });

    (function frame(t) {
      const r = canvas.getBoundingClientRect();
      const W = r.width, H = r.height;
      ctx.clearRect(0, 0, W, H);
      const cx = W * 0.62, cy = H * 0.5;
      const R = Math.min(W, H) * 0.32;
      const time = t * 0.0004;
      const ry = time + (mouse.x / W - 0.5) * 0.8;
      const rx = Math.sin(time * 0.7) * 0.4 + (mouse.y / H - 0.5) * 0.6;
      const cyA = Math.cos(ry), syA = Math.sin(ry);
      const cxA = Math.cos(rx), sxA = Math.sin(rx);
      const isDark = document.documentElement.dataset.theme !== "light";

      const projected = pts.map((p) => {
        // ノイズ的な歪み
        const n = 1 + 0.12 * Math.sin(p.x * 4 + time * 3) * Math.cos(p.y * 4 - time * 2);
        let x = p.x * n, y = p.y * n, z = p.z * n;
        // Y軸回転
        let x1 = x * cyA + z * syA, z1 = -x * syA + z * cyA;
        // X軸回転
        let y1 = y * cxA - z1 * sxA, z2 = y * sxA + z1 * cxA;
        const scale = 1 / (2.2 - z2 * 0.6);
        return { sx: cx + x1 * R * scale * 2, sy: cy + y1 * R * scale * 2, z: z2, s: scale };
      });
      projected.sort((a, b) => a.z - b.z);
      for (const p of projected) {
        const depth = (p.z + 1) / 2;
        ctx.beginPath();
        ctx.fillStyle = isDark
          ? `hsla(${160 + depth * 160}, 90%, ${45 + depth * 35}%, ${0.25 + depth * 0.75})`
          : `hsla(${160 + depth * 160}, 80%, ${30 + depth * 25}%, ${0.3 + depth * 0.7})`;
        ctx.arc(p.sx, p.sy, 1.2 + depth * 2.2 * p.s, 0, Math.PI * 2);
        ctx.fill();
      }
      requestAnimationFrame(frame);
    })(0);
  }

  /* ---------- 5. タイピング演出 ---------- */
  function startTyping() {
    const el = $("#typed");
    const words = ["Creative Engineer.", "Interaction Designer.", "WebGL Tinkerer.", "Pixel Obsessive."];
    let w = 0, c = 0, deleting = false;
    const step = () => {
      const word = words[w];
      el.textContent = deleting ? word.slice(0, c--) : word.slice(0, c++);
      let delay = deleting ? 45 : 90;
      if (!deleting && c > word.length) { deleting = true; delay = 1600; }
      else if (deleting && c < 0) { deleting = false; w = (w + 1) % words.length; c = 0; delay = 400; }
      setTimeout(step, delay);
    };
    step();
  }

  /* ---------- 6. グリッチ用：data-text 同期 ---------- */
  function glitchInit() {
    $$(".glitch").forEach((el) => el.setAttribute("data-text", el.textContent.trim()));
  }

  /* ---------- 7. スクロール演出 ---------- */
  function revealOnScroll() {
    const io = new IntersectionObserver((entries) => {
      for (const e of entries) {
        if (e.isIntersecting) {
          e.target.classList.add("in");
          // 同時に出る要素は少しずつ遅らせる
          const siblings = [...e.target.parentElement.children].filter((c) => c.classList.contains("reveal"));
          const idx = siblings.indexOf(e.target);
          e.target.style.setProperty("--d", idx * 0.08 + "s");
          io.unobserve(e.target);
        }
      }
    }, { threshold: 0.15 });
    $$(".reveal").forEach((el) => io.observe(el));
  }

  function progressBar() {
    const bar = $("#progress");
    addEventListener("scroll", () => {
      const max = document.documentElement.scrollHeight - innerHeight;
      bar.style.width = (scrollY / max) * 100 + "%";
    }, { passive: true });
  }

  /* ---------- 8. 数字カウントアップ ---------- */
  function counters() {
    const io = new IntersectionObserver((entries) => {
      for (const e of entries) {
        if (!e.isIntersecting) continue;
        const el = e.target, target = +el.dataset.count;
        const start = performance.now(), dur = 1600;
        const tick = (now) => {
          const p = Math.min((now - start) / dur, 1);
          el.textContent = Math.round(target * (1 - Math.pow(1 - p, 3)));
          if (p < 1) requestAnimationFrame(tick);
        };
        requestAnimationFrame(tick);
        io.unobserve(el);
      }
    }, { threshold: 0.5 });
    $$("[data-count]").forEach((el) => io.observe(el));
  }

  /* ---------- 9. 3D チルトカード ---------- */
  function tilt() {
    if (!isFine) return;
    $$(".tilt").forEach((card) => {
      card.addEventListener("mousemove", (e) => {
        const r = card.getBoundingClientRect();
        const px = (e.clientX - r.left) / r.width;
        const py = (e.clientY - r.top) / r.height;
        card.style.transform = `perspective(900px) rotateX(${(0.5 - py) * 12}deg) rotateY(${(px - 0.5) * 14}deg) translateZ(8px)`;
        card.style.setProperty("--mx", px * 100 + "%");
        card.style.setProperty("--my", py * 100 + "%");
      });
      card.addEventListener("mouseleave", () => (card.style.transform = ""));
    });
  }

  /* ---------- 10. ラボ：フローフィールド ---------- */
  function flowField() {
    if (prefersReduced) return;
    const canvas = $("#labFlow");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    let w, h, parts, attractor = null;
    const resize = () => {
      w = canvas.width = canvas.clientWidth * devicePixelRatio;
      h = canvas.height = canvas.clientHeight * devicePixelRatio;
      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
      parts = Array.from({ length: 500 }, () => ({ x: Math.random() * canvas.clientWidth, y: Math.random() * canvas.clientHeight, life: Math.random() }));
    };
    resize();
    addEventListener("resize", resize);
    canvas.addEventListener("pointerdown", (e) => {
      const r = canvas.getBoundingClientRect();
      attractor = { x: e.clientX - r.left, y: e.clientY - r.top };
    });
    canvas.addEventListener("pointerup", () => (attractor = null));
    canvas.addEventListener("pointerleave", () => (attractor = null));
    canvas.addEventListener("pointermove", (e) => {
      if (!attractor) return;
      const r = canvas.getBoundingClientRect();
      attractor.x = e.clientX - r.left; attractor.y = e.clientY - r.top;
    });

    (function frame(t) {
      const W = canvas.clientWidth, H = canvas.clientHeight;
      ctx.fillStyle = "rgba(7,7,11,0.12)";
      if (document.documentElement.dataset.theme === "light") ctx.fillStyle = "rgba(245,243,238,0.12)";
      ctx.fillRect(0, 0, W, H);
      const time = t * 0.0002;
      for (const p of parts) {
        const angle = (Math.sin(p.x * 0.01 + time) + Math.cos(p.y * 0.01 - time)) * Math.PI;
        p.x += Math.cos(angle) * 1.4;
        p.y += Math.sin(angle) * 1.4;
        if (attractor) {
          const dx = attractor.x - p.x, dy = attractor.y - p.y;
          const d = Math.hypot(dx, dy) + 1;
          p.x += (dx / d) * 2.5; p.y += (dy / d) * 2.5;
        }
        if (p.x < 0 || p.x > W || p.y < 0 || p.y > H) {
          p.x = Math.random() * W; p.y = Math.random() * H;
        }
        ctx.fillStyle = `hsla(${(p.x / W) * 120 + 150}, 90%, 65%, 0.7)`;
        ctx.fillRect(p.x, p.y, 1.4, 1.4);
      }
      requestAnimationFrame(frame);
    })(0);
  }

  /* ---------- 11. ラボ：磁石ボックス ---------- */
  function magnetLab() {
    const box = $("#labMagnet");
    if (!box) return;
    const label = box.querySelector("span");
    box.addEventListener("mousemove", (e) => {
      const r = box.getBoundingClientRect();
      const x = (e.clientX - r.left - r.width / 2) * 0.35;
      const y = (e.clientY - r.top - r.height / 2) * 0.35;
      label.style.transform = `translate(${x}px, ${y}px) rotate(${x * 0.1}deg)`;
    });
    box.addEventListener("mouseleave", () => (label.style.transform = ""));
  }

  /* ---------- 12. テーマ切替（View Transitions対応） ---------- */
  function themeToggle() {
    const btn = $("#themeToggle");
    const saved = localStorage.getItem("theme");
    if (saved) document.documentElement.dataset.theme = saved;
    btn.addEventListener("click", (e) => {
      const next = document.documentElement.dataset.theme === "light" ? "dark" : "light";
      btn.classList.add("spin");
      setTimeout(() => btn.classList.remove("spin"), 600);
      const apply = () => {
        document.documentElement.dataset.theme = next;
        localStorage.setItem("theme", next);
      };
      if (document.startViewTransition && !prefersReduced) {
        const x = e.clientX, y = e.clientY;
        const r = Math.hypot(Math.max(x, innerWidth - x), Math.max(y, innerHeight - y));
        const t = document.startViewTransition(apply);
        t.ready.then(() => {
          document.documentElement.animate(
            { clipPath: [`circle(0px at ${x}px ${y}px)`, `circle(${r}px at ${x}px ${y}px)`] },
            { duration: 700, easing: "cubic-bezier(0.2,0.8,0.2,1)", pseudoElement: "::view-transition-new(root)" }
          );
        });
      } else {
        apply();
      }
    });
  }

  /* ---------- 13. 隠しターミナル + Konamiコード ---------- */
  function terminal() {
    const term = $("#terminal"), form = $("#termForm"), input = $("#termInput"), body = $("#termBody");
    const open = () => { term.hidden = false; input.focus(); };
    const close = () => { term.hidden = true; };
    const print = (t, cls = "") => {
      const d = document.createElement("div");
      d.className = cls; d.textContent = t; body.appendChild(d);
      body.scrollTop = body.scrollHeight;
    };
    const commands = {
      help: () => "commands: about, work, theme, matrix, whoami, clear, exit",
      about: () => "Creative engineer. Building experiences that feel like magic.",
      work: () => "1) Prism Commerce  2) Pulse Dashboard  3) Echo Notes",
      whoami: () => "visitor — welcome to the other side of the screen.",
      theme: () => { $("#themeToggle").click(); return "theme toggled."; },
      matrix: () => { startMatrix(); return "wake up, neo..."; },
      clear: () => { body.innerHTML = ""; return null; },
      exit: () => { close(); return null; },
    };
    const konami = ["ArrowUp","ArrowUp","ArrowDown","ArrowDown","ArrowLeft","ArrowRight","ArrowLeft","ArrowRight","b","a"];
    let kIdx = 0;
    addEventListener("keydown", (e) => {
      const key = e.key.length === 1 ? e.key.toLowerCase() : e.key;
      if (key === konami[kIdx]) {
        kIdx++;
        if (kIdx === konami.length) { kIdx = 0; open(); print("🎮 KONAMI unlocked."); }
      } else {
        kIdx = key === konami[0] ? 1 : 0;
      }
      if (e.key === "`") { e.preventDefault(); term.hidden ? open() : close(); }
      if (e.key === "Escape" && !term.hidden) close();
    });
    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const cmd = input.value.trim();
      input.value = "";
      if (!cmd) return;
      print("➜ " + cmd, "");
      const fn = commands[cmd.toLowerCase()];
      const res = fn ? fn() : `command not found: ${cmd}`;
      if (res) print(res, fn ? "" : "err");
    });
  }

  function startMatrix() {
    const c = document.createElement("canvas");
    c.style.cssText = "position:fixed;inset:0;z-index:600;pointer-events:none;opacity:.85";
    document.body.appendChild(c);
    const ctx = c.getContext("2d");
    c.width = innerWidth; c.height = innerHeight;
    const cols = Math.floor(c.width / 16);
    const drops = Array(cols).fill(0);
    const iv = setInterval(() => {
      ctx.fillStyle = "rgba(0,0,0,0.08)";
      ctx.fillRect(0, 0, c.width, c.height);
      ctx.fillStyle = "#7cf7d4";
      ctx.font = "16px monospace";
      drops.forEach((y, i) => {
        ctx.fillText(String.fromCharCode(0x30a0 + Math.random() * 96), i * 16, y * 16);
        drops[i] = y * 16 > c.height && Math.random() > 0.975 ? 0 : y + 1;
      });
    }, 40);
    setTimeout(() => { clearInterval(iv); c.remove(); }, 6000);
  }

  /* ---------- 14. その他 ---------- */
  function misc() {
    $("#year").textContent = new Date().getFullYear();
    // ヒーローのテキストに軽い視差
    addEventListener("scroll", () => {
      if (prefersReduced) return;
      const y = scrollY;
      const c = $(".hero-content");
      if (c) c.style.transform = `translateY(${y * 0.25}px)`;
    }, { passive: true });
  }

  /* ---------- 起動 ---------- */
  document.addEventListener("DOMContentLoaded", () => {
    glitchInit();
    boot();
    cursor();
    particles();
    orb();
    tilt();
    counters();
    progressBar();
    flowField();
    magnetLab();
    themeToggle();
    terminal();
    misc();
  });
})();

