/* ==========================================================
   Developer Portfolio — styles
   ========================================================== */
:root {
  --bg: #07070b;
  --fg: #ecebf5;
  --muted: #8a8aa3;
  --accent: #7cf7d4;
  --accent-2: #ff5fd2;
  --accent-3: #ffd166;
  --card: rgba(255, 255, 255, 0.04);
  --line: rgba(255, 255, 255, 0.12);
  --ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --font-display: "Space Grotesk", "Noto Sans JP", system-ui, sans-serif;
  --font-body: "Inter", "Noto Sans JP", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
}

:root[data-theme="light"] {
  --bg: #f5f3ee;
  --fg: #101018;
  --muted: #5b5b6e;
  --accent: #0a8f74;
  --accent-2: #d1248f;
  --accent-3: #c98a00;
  --card: rgba(0, 0, 0, 0.04);
  --line: rgba(0, 0, 0, 0.12);
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  background: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
  line-height: 1.7;
  overflow-x: hidden;
  transition: background 0.6s var(--ease), color 0.6s var(--ease);
}
body.locked { overflow: hidden; }
a { color: inherit; text-decoration: none; }
::selection { background: var(--accent-2); color: #000; }

/* ---------- Loader ---------- */
#loader {
  position: fixed; inset: 0; z-index: 1000;
  background: #000; color: var(--accent);
  display: grid; place-content: center; gap: 24px;
  transition: opacity 0.8s var(--ease), visibility 0.8s;
}
#loader.done { opacity: 0; visibility: hidden; }
.boot-text {
  font-family: var(--font-mono); font-size: clamp(12px, 1.6vw, 15px);
  min-height: 9em; min-width: min(560px, 86vw); white-space: pre-wrap;
}
.loader-bar { width: min(560px, 86vw); height: 2px; background: #222; overflow: hidden; }
.loader-bar span {
  display: block; height: 100%; width: 0;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  animation: load 1.8s var(--ease) forwards;
}
@keyframes load { to { width: 100%; } }

/* ---------- Background canvas ---------- */
#bg {
  position: fixed; inset: 0; width: 100%; height: 100%;
  z-index: -1; pointer-events: none; opacity: 0.8;
}

/* ---------- Custom cursor ---------- */
.cursor-dot, .cursor-ring {
  position: fixed; top: 0; left: 0; pointer-events: none; z-index: 999;
  border-radius: 50%; transform: translate(-50%, -50%);
  mix-blend-mode: difference;
}
.cursor-dot { width: 8px; height: 8px; background: #fff; }
.cursor-ring {
  width: 40px; height: 40px; border: 1.5px solid #fff;
  transition: width 0.3s var(--ease), height 0.3s var(--ease), background 0.3s;
}
.cursor-ring.hover { width: 84px; height: 84px; background: rgba(255,255,255,0.15); }
@media (hover: none) { .cursor-dot, .cursor-ring { display: none; } }
@media (hover: hover) { body { cursor: none; } a, button, .tilt, .lab-magnet, canvas { cursor: none; } }

/* ---------- Progress ---------- */
.progress {
  position: fixed; top: 0; left: 0; height: 3px; width: 0%; z-index: 200;
  background: linear-gradient(90deg, var(--accent), var(--accent-2), var(--accent-3));
}

/* ---------- Nav ---------- */
.nav {
  position: fixed; top: 0; left: 0; right: 0; z-index: 100;
  display: flex; align-items: center; justify-content: space-between;
  padding: 18px clamp(20px, 5vw, 64px);
  backdrop-filter: blur(12px);
  background: linear-gradient(var(--bg), transparent);
}
.logo { font-family: var(--font-display); font-weight: 700; font-size: 1.3rem; position: relative; }
.logo span { color: var(--accent); }
.logo:hover::after {
  content: attr(data-text); position: absolute; inset: 0; color: var(--accent-2);
  clip-path: inset(0 0 60% 0); transform: translate(3px, -2px);
}
.nav nav { display: flex; gap: clamp(14px, 2.5vw, 32px); font-family: var(--font-mono); font-size: 0.85rem; }
.nav nav a { position: relative; }
.nav nav a::after {
  content: ""; position: absolute; left: 0; bottom: -4px; height: 1px; width: 0;
  background: var(--accent); transition: width 0.4s var(--ease);
}
.nav nav a:hover::after { width: 100%; }
.theme-toggle {
  width: 40px; height: 40px; border-radius: 50%; border: 1px solid var(--line);
  background: var(--card); color: var(--fg); font-size: 1.1rem;
  transition: transform 0.6s var(--ease);
}
.theme-toggle.spin { transform: rotate(360deg); }

/* ---------- Magnetic ---------- */
.magnetic { display: inline-block; transition: transform 0.3s var(--ease); will-change: transform; }

/* ---------- Hero ---------- */
.hero {
  position: relative; min-height: 100vh; display: grid; align-items: center;
  padding: 120px clamp(20px, 6vw, 96px) 80px; overflow: hidden;
}
.hero-canvas-wrap {
  position: absolute; inset: 0; z-index: -1; opacity: 0.9;
  -webkit-mask-image: radial-gradient(ellipse at 70% 50%, #000 30%, transparent 70%);
          mask-image: radial-gradient(ellipse at 70% 50%, #000 30%, transparent 70%);
}
#orb { width: 100%; height: 100%; display: block; }
.hero-content { max-width: 900px; }
.eyebrow { font-family: var(--font-mono); color: var(--accent); letter-spacing: 0.1em; }
h1 {
  font-family: var(--font-display);
  font-size: clamp(3.2rem, 11vw, 9.5rem);
  line-height: 0.95; letter-spacing: -0.04em; font-weight: 700;
  margin: 0.2em 0 0.1em;
  background: linear-gradient(100deg, var(--fg) 30%, var(--accent) 60%, var(--accent-2));
  -webkit-background-clip: text; background-clip: text; color: transparent;
  background-size: 200% auto; animation: shine 6s linear infinite;
}
@keyframes shine { to { background-position: 200% center; } }
/* グリッチ効果 */
.glitch { position: relative; }
.glitch::before, .glitch::after {
  content: attr(data-text); position: absolute; left: 0; top: 0; width: 100%;
  background: inherit; -webkit-background-clip: text; background-clip: text;
  color: transparent; opacity: 0; pointer-events: none;
}
.glitch:hover::before { opacity: 0.7; animation: glitch1 0.6s steps(2) infinite; color: var(--accent-2); -webkit-text-fill-color: var(--accent-2); }
.glitch:hover::after  { opacity: 0.7; animation: glitch2 0.6s steps(2) infinite; color: var(--accent); -webkit-text-fill-color: var(--accent); }
@keyframes glitch1 { 0%{clip-path:inset(10% 0 70% 0);transform:translate(-4px,0)} 50%{clip-path:inset(60% 0 10% 0);transform:translate(4px,0)} 100%{clip-path:inset(30% 0 40% 0);transform:translate(-2px,0)} }
@keyframes glitch2 { 0%{clip-path:inset(70% 0 5% 0);transform:translate(4px,0)} 50%{clip-path:inset(20% 0 60% 0);transform:translate(-4px,0)} 100%{clip-path:inset(50% 0 20% 0);transform:translate(2px,0)} }

.role { font-family: var(--font-mono); font-size: clamp(1rem, 2.4vw, 1.5rem); color: var(--muted); min-height: 2em; }
.caret { color: var(--accent); animation: blink 1s steps(2) infinite; }
@keyframes blink { 50% { opacity: 0; } }

.hero-cta { display: flex; flex-wrap: wrap; gap: 14px; margin-top: 36px; }
.btn {
  position: relative; display: inline-flex; gap: 10px; align-items: center;
  padding: 14px 26px; border-radius: 999px; border: 1px solid var(--accent);
  background: var(--accent); color: #000; font-weight: 600; overflow: hidden;
  isolation: isolate;
}
.btn::before {
  content: ""; position: absolute; inset: 0; z-index: -1; transform: translateY(101%);
  background: var(--accent-2); transition: transform 0.5s var(--ease);
}
.btn:hover::before { transform: translateY(0); }
.btn:hover span { transform: translateX(6px); }
.btn span { transition: transform 0.4s var(--ease); }
.btn.ghost { background: transparent; color: var(--fg); border-color: var(--line); }
.btn.ghost::before { background: var(--fg); }
.btn.ghost:hover { color: var(--bg); }

.scroll-hint {
  position: absolute; bottom: 36px; left: clamp(20px, 6vw, 96px);
  font-family: var(--font-mono); font-size: 0.75rem; color: var(--muted);
  display: flex; align-items: center; gap: 12px; letter-spacing: 0.2em;
}
.scroll-hint span {
  width: 1px; height: 48px; background: var(--line); position: relative; overflow: hidden;
}
.scroll-hint span::after {
  content: ""; position: absolute; top: -100%; left: 0; width: 100%; height: 100%;
  background: var(--accent); animation: drip 2s var(--ease) infinite;
}
@keyframes drip { to { top: 100%; } }

/* ---------- Reveal on scroll ---------- */
.reveal {
  opacity: 0; transform: translateY(40px) scale(0.98);
  filter: blur(8px);
  transition: opacity 0.9s var(--ease), transform 0.9s var(--ease), filter 0.9s var(--ease);
  transition-delay: var(--d, 0s);
}
.reveal.in { opacity: 1; transform: none; filter: none; }

/* ---------- Sections ---------- */
.section { padding: clamp(80px, 12vw, 160px) clamp(20px, 6vw, 96px); position: relative; }
.section-title {
  font-family: var(--font-display); font-size: clamp(2rem, 5vw, 3.6rem);
  letter-spacing: -0.03em; margin-bottom: 56px;
  display: flex; align-items: baseline; gap: 16px;
}
.section-title .num { font-family: var(--font-mono); font-size: 0.9rem; color: var(--accent-2); }

/* About */
.about-grid { display: grid; grid-template-columns: 1.2fr 1fr; gap: clamp(32px, 6vw, 96px); align-items: start; }
.lead { font-family: var(--font-display); font-size: clamp(1.5rem, 3vw, 2.2rem); line-height: 1.35; margin-bottom: 24px; }
.about-text p:not(.lead) { color: var(--muted); max-width: 56ch; }
.stats { list-style: none; display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.stats li {
  border: 1px solid var(--line); border-radius: 20px; padding: 28px;
  background: var(--card); backdrop-filter: blur(6px);
}
.stats strong { display: block; font-family: var(--font-display); font-size: clamp(2.2rem, 4vw, 3.2rem); color: var(--accent); line-height: 1; }
.stats span { font-family: var(--font-mono); font-size: 0.8rem; color: var(--muted); text-transform: uppercase; letter-spacing: 0.1em; }

.skills { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 64px; }
.skills span {
  padding: 8px 16px; border: 1px solid var(--line); border-radius: 999px;
  font-family: var(--font-mono); font-size: 0.85rem; transition: all 0.3s var(--ease);
}
.skills span:hover { background: var(--accent); color: #000; border-color: var(--accent); transform: translateY(-3px) rotate(-2deg); }

/* Work cards */
.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 28px; }
.card {
  position: relative; border-radius: 24px; overflow: hidden;
  background: var(--card); border: 1px solid var(--line);
  transform-style: preserve-3d; transition: transform 0.2s ease-out, box-shadow 0.4s;
}
.card:hover { box-shadow: 0 30px 80px -20px rgba(124, 247, 212, 0.25); }
.card::after { /* 光の反射 */
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%), rgba(255,255,255,0.18), transparent 40%);
  opacity: 0; transition: opacity 0.3s;
}
.card:hover::after { opacity: 1; }
.card-visual { aspect-ratio: 16 / 10; position: relative; overflow: hidden; }
.card-visual::before {
  content: ""; position: absolute; inset: -50%;
  animation: spin 14s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }
.v1::before { background: conic-gradient(from 0deg, #7cf7d4, #ff5fd2, #ffd166, #7cf7d4); filter: blur(30px); }
.v2::before { background: repeating-radial-gradient(circle at 50% 50%, #7cf7d4 0 4px, transparent 4px 18px); animation-duration: 30s; }
.v3::before { background: linear-gradient(120deg, #ff5fd2, #5a7bff, #7cf7d4, #ff5fd2); background-size: 300% 300%; inset: 0; animation: shiftbg 6s ease infinite; }
@keyframes shiftbg { 0%,100%{background-position:0% 50%} 50%{background-position:100% 50%} }
.card-body { padding: 26px; }
.card-body h3 { font-family: var(--font-display); font-size: 1.5rem; margin-bottom: 8px; }
.card-body p { color: var(--muted); font-size: 0.95rem; }
.tags { display: flex; gap: 8px; margin-top: 18px; flex-wrap: wrap; }
.tags span { font-family: var(--font-mono); font-size: 0.75rem; padding: 4px 10px; border-radius: 6px; background: var(--card); border: 1px solid var(--line); }

/* Lab */
.lab-intro { color: var(--muted); margin-bottom: 40px; }
.lab-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 28px; }
.lab-item {
  border: 1px solid var(--line); border-radius: 24px; overflow: hidden;
  background: var(--card); display: flex; flex-direction: column;
}
.lab-item canvas { width: 100%; height: 320px; display: block; }
.lab-item > span { padding: 16px 20px; font-family: var(--font-mono); font-size: 0.85rem; color: var(--muted); }
.lab-magnet {
  height: 320px; display: grid; place-items: center; position: relative;
  font-family: var(--font-display); font-size: 2.2rem; font-weight: 700;
}
.lab-magnet span {
  padding: 40px 56px; border-radius: 40px; border: 1px solid var(--accent);
  transition: transform 0.25s var(--ease), background 0.4s;
}
.lab-magnet:hover span { background: var(--accent); color: #000; }

/* Contact */
.contact { text-align: left; }
.big { font-family: var(--font-display); font-size: clamp(2.2rem, 6vw, 5rem); line-height: 1.05; letter-spacing: -0.03em; margin-bottom: 40px; }
.mail-link {
  font-family: var(--font-display); font-size: clamp(1.4rem, 4vw, 2.8rem); color: var(--accent);
  border-bottom: 2px solid var(--accent-2); padding-bottom: 4px;
}
.hint { margin-top: 56px; font-family: var(--font-mono); font-size: 0.85rem; color: var(--muted); }
kbd {
  font-family: var(--font-mono); padding: 2px 8px; border: 1px solid var(--line);
  border-radius: 6px; background: var(--card); color: var(--fg);
}

footer {
  padding: 48px clamp(20px, 6vw, 96px); border-top: 1px solid var(--line);
  font-family: var(--font-mono); font-size: 0.85rem; color: var(--muted);
}

/* ---------- Hidden terminal ---------- */
.terminal {
  position: fixed; left: 50%; top: 50%; transform: translate(-50%, -50%);
  width: min(720px, 92vw); height: min(460px, 70vh); z-index: 500;
  background: rgba(8, 10, 14, 0.96); color: #c8ffe9;
  border: 1px solid var(--accent); border-radius: 14px;
  box-shadow: 0 40px 120px rgba(0,0,0,0.6), 0 0 40px rgba(124,247,212,0.2);
  font-family: var(--font-mono); font-size: 14px;
  display: flex; flex-direction: column; overflow: hidden;
  animation: termIn 0.35s var(--ease);
}
.terminal[hidden] { display: none; }
@keyframes termIn { from { opacity: 0; transform: translate(-50%, -46%) scale(0.96); } }
.term-head {
  display: flex; align-items: center; gap: 8px; padding: 10px 14px;
  background: rgba(255,255,255,0.05); border-bottom: 1px solid var(--line);
}
.term-head span { width: 11px; height: 11px; border-radius: 50%; background: #ff5f57; }
.term-head span:nth-child(2) { background: #febc2e; }
.term-head span:nth-child(3) { background: #28c840; }
.term-head strong { margin-left: auto; font-weight: 400; color: var(--muted); font-size: 12px; }
.term-body { flex: 1; overflow-y: auto; padding: 14px 16px; white-space: pre-wrap; }
.term-body b { color: var(--accent); font-weight: 600; }
.term-body .err { color: var(--accent-2); }
#termForm { display: flex; gap: 10px; padding: 10px 16px; border-top: 1px solid var(--line); }
.prompt { color: var(--accent); }
#termInput {
  flex: 1; background: transparent; border: 0; outline: none;
  color: inherit; font: inherit;
}

/* ---------- Responsive ---------- */
@media (max-width: 860px) {
  .about-grid { grid-template-columns: 1fr; }
  .nav nav { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
  html { scroll-behavior: auto; }
}
